import type { Hearts } from './types.js';

export const MAX_HEARTS = 5;
export const REGEN_MS = 1_800_000;

/** §7.3: restore hearts that regenerated by timer since lastRegenAt. */
export function regen(h: Hearts, now: number): Hearts {
  if (h.count >= MAX_HEARTS) return { count: MAX_HEARTS, lastRegenAt: now };
  if (now < h.lastRegenAt) return { count: h.count, lastRegenAt: now };
  const gained = Math.floor((now - h.lastRegenAt) / REGEN_MS);
  const count = Math.min(MAX_HEARTS, h.count + gained);
  const lastRegenAt = count === MAX_HEARTS ? now : h.lastRegenAt + gained * REGEN_MS;
  return { count, lastRegenAt };
}

export function loseHeart(h: Hearts, now: number): Hearts {
  const r = regen(h, now);
  const lastRegenAt = r.count === MAX_HEARTS ? now : r.lastRegenAt;
  return { count: Math.max(0, r.count - 1), lastRegenAt };
}

export function gainHeart(h: Hearts, now: number): Hearts {
  const r = regen(h, now);
  const count = Math.min(MAX_HEARTS, r.count + 1);
  return { count, lastRegenAt: count === MAX_HEARTS ? now : r.lastRegenAt };
}

export function msToNextHeart(h: Hearts, now: number): number | null {
  if (h.count >= MAX_HEARTS) return null;
  if (now < h.lastRegenAt) return REGEN_MS;
  return REGEN_MS - ((now - h.lastRegenAt) % REGEN_MS);
}
